files.content:
.skeleton-stack{
  display:grid;
  gap:var(--s-3);
  width:100%;
}
.skeleton-line, .skeleton-circle, .skeleton-block{
  position:relative;
  overflow:hidden;
  background:var(--obsidian-700);
}
.skeleton-line{
  height:var(--s-3);
  border-radius:var(--r-sm);
}
.skeleton-circle{
  --size:var(--s-8);
  flex:none;
  width:var(--size);
  height:var(--size);
  border-radius:var(--r-full);
}
.skeleton-block{
  width:100%;
  height:var(--s-24);
  border-radius:var(--r-md);
}
.skeleton-line::after, .skeleton-circle::after, .skeleton-block::after{
  content:"";
  position:absolute;
  inset:0;
  background:linear-gradient( 90deg, transparent 0, color-mix(in srgb, var(--primary-500) calc(var(--tint-fill) * 100%), transparent) 50%, transparent 100% );
  animation:skeleton-shimmer 1600ms linear infinite;
}
@media (prefers-reduced-motion: reduce){
  .skeleton-line::after, .skeleton-circle::after, .skeleton-block::after{
    animation:none;
    opacity:0;
  }
}
